'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');
const P=require('./policy.cjs'),S=require('./source-bundle.cjs'),E=require('./envelope.cjs'),F=require('./fixtures.cjs'),Pre=require('./preflight.cjs'),Operator=require('./operator.cjs'),Publisher=require('./publisher.cjs');
test('new target binds exact252 commit blobs and one13to17 overlay without changing original files',()=>{const f=F.source(),a=S.verifyFiles(f.manifest,f.files),z=S.overlay(a);assert.equal(P.SOURCE,'45facc279cf27b20c2a84777d4a1a671af883c87');assert.equal(P.VERSION,17);assert.equal(S.COUNT,252);assert.equal(a.length,252);for(let i=0;i<a.length;i++){if(a[i].path==='app.config.ts'){assert.ok(a[i].bytes.toString().includes("buildNumber: '13'"));assert.ok(z[i].bytes.toString().includes("buildNumber: '17'"));assert.ok(z[i].bytes.toString().includes("CFBundleDevelopmentRegion: 'en'"));assert.ok(z[i].bytes.toString().includes('versionCode: 15'));assert.equal(z[i].bytes.toString().replace("buildNumber: '17'","buildNumber: '13'"),a[i].bytes.toString());}else assert.equal(z[i].bytes,a[i].bytes);}});
test('domain/version isolation keeps full AEAD authentication and rejects preceding native16 context',()=>{const a=F.approval(),k=Buffer.alloc(32,8),v={operationId:a.operationId,direction:'INPUT',workflowCommit:a.workflowCommit,sourceReviewSha256:a.sourceReviewSha256,nativeSource:P.SOURCE,backendSource:P.BACKEND_SOURCE,version:17};const x=E.seal(Buffer.from('test'),k,v,Buffer.alloc(12,8));assert.equal(E.open(x,k,v).toString(),'test');assert.throws(()=>E.open(x,k,{...v,version:16}));});
test('standalone operators and publication imports are pure until explicit authorized mode',async()=>{assert.equal((await Operator.main([])).credentialReads,0);assert.equal(Publisher.main([]).providerOperations,0);assert.throws(()=>Publisher.main(['--publish','bad']));});
test('English camera baseline and localization contract bind source truth while preserving byte algorithms',()=>{const py='C:/Users/runge/.cache/codex-runtimes/codex-primary-runtime/dependencies/python/python.exe';const code="import ast,hashlib,json,pathlib; root=pathlib.Path(r'C:/Users/runge/.nevermonday-secrets/ios17-ui-redesign-20261008'); old=pathlib.Path(r'C:/Users/runge/.nevermonday-secrets/ios16-protected-github-macos-signature-capacity-20261006'); names=['executable','signature_capacity','signature_failure_shape','runtime_config_proof','bundle_runtime_proof','archive_runtime_proof','runtime_config_preflight','_unique_runtime_object','_invalid_runtime_constant']; tables=[{n.name:ast.dump(n,include_attributes=False) for n in ast.parse((p/'native-audit.py').read_text(encoding='utf-8-sig')).body if isinstance(n,ast.FunctionDef)} for p in [root,old]]; assert all(tables[0][n]==tables[1][n] for n in names); print(json.dumps({'immutableAlgorithms':len(names)}))";const r=cp.spawnSync(py,['-c',code],{shell:false,encoding:'utf8',maxBuffer:65536});assert.equal(r.status,0);assert.equal(JSON.parse(r.stdout).immutableAlgorithms,9);const feature=fs.readFileSync(path.join(__dirname,'feature_guard.py'),'utf8'),native=fs.readFileSync(path.join(__dirname,'native-audit.py'),'utf8');assert.ok(feature.includes("'cameraPurposeEnglishExact': info.get('NSCameraUsageDescription') == BASE_CAMERA"));assert.ok(feature.includes('No photos are saved or uploaded.'));assert.ok(native.includes("info.get('CFBundleDevelopmentRegion')=='en'"));assert.ok(native.includes("info.get('CFBundleVersion')=='17'"));});
test('immutable preflight expands exact reviewed workflow allowlist only with own17',()=>{assert.deepEqual(Pre.WORKFLOWS,['.github/workflows/nm-ios16-toolchain-probe.yml','.github/workflows/nm-protected-ios16.yml','.github/workflows/nm-protected-ios17.yml']);assert.equal(Pre.COUNT,57);assert.throws(()=>Pre.create({},null,{},null,null,P));});
